cd /tmp/shot-tools && cat > interact.mjs <<'EOF'
import { chromium } from 'playwright';
import { execSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
const port = readFileSync('/tmp/vite-mine.port', 'utf8').trim();
const url = `http://127.0.0.1:${port}/`;
const exe = execSync('find /home/node/.cache/ms-playwright -type f -path "*headless_shell" | head -1').toString().trim();
const browser = await chromium.launch({ executablePath: exe, args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage'] });
const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
const errors = [];
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(`[${m.type()}] ${m.text()}`); });
page.on('pageerror', (e) => errors.push(`[pageerror] ${e.message}\n${e.stack}`));
await page.goto(url, { waitUntil: 'networkidle' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'networkidle' });
await page.waitForTimeout(400);

const geom = () => page.evaluate(() => Object.fromEntries([...document.querySelectorAll('.widget')].map(w => [w.querySelector('h2').textContent, { l: Math.round(parseFloat(w.style.left)), t: Math.round(parseFloat(w.style.top)), w: Math.round(parseFloat(w.style.width)), h: Math.round(parseFloat(w.style.height)) }])));
const check = async (label) => {
  const g = await geom();
  const boxes = Object.entries(g);
  const overlaps = [];
  for (let i = 0; i < boxes.length; i++) for (let j = i + 1; j < boxes.length; j++) {
    const a = boxes[i][1], b = boxes[j][1];
    if (a.l < b.l + b.w && b.l < a.l + a.w && a.t < b.t + b.h && b.t < a.t + a.h) overlaps.push(`${boxes[i][0]} x ${boxes[j][0]}`);
  }
  console.log(`[${label}] overlaps:`, overlaps.length ? overlaps : 'none');
  return g;
};

await check('initial');

// 1. Drag "Заказы" header to the right end of the row with plan.
const header = page.locator('.widget', { hasText: 'Заказы' }).locator('.widget-header');
const hb = await header.boundingBox();
await page.mouse.move(hb.x + 120, hb.y + 20);
await page.mouse.down();
for (let s = 1; s <= 12; s++) await page.mouse.move(hb.x + 120 + s * 30, hb.y + 20 + s * 40);
await page.waitForTimeout(250);
await page.screenshot({ path: '/tmp/shot-tools/dragging.png' });
await page.mouse.up();
await page.waitForTimeout(300);
await check('after drag Заказы');
console.log('stored:', await page.evaluate(() => localStorage.getItem('dashboard-layout:v1')?.slice(0, 120)));

// 2. Resize the plan widget by dragging its corner.
const plan = page.locator('.widget', { hasText: 'План продаж' });
const pb = await plan.boundingBox();
await page.mouse.move(pb.x + pb.width - 6, pb.y + pb.height - 6);
await page.mouse.down();
for (let s = 1; s <= 8; s++) await page.mouse.move(pb.x + pb.width - 6 + s * 25, pb.y + pb.height - 6);
await page.mouse.up();
await page.waitForTimeout(300);
await check('after resize План');

// 3. Keyboard: focus conversion header, move with arrows, resize with shift.
const conv = page.locator('.widget', { hasText: 'Конверсия' }).locator('.widget-header');
await conv.focus();
await page.keyboard.press('ArrowLeft');
await page.keyboard.press('Shift+ArrowDown');
await page.waitForTimeout(300);
await check('after keyboard Конверсия');

// 4. Table toggle on traffic widget.
await page.locator('.widget', { hasText: 'Визиты по дням' }).locator('.widget-toggle').click();
await page.waitForTimeout(200);
console.log('table visible in traffic:', await page.locator('.widget', { hasText: 'Визиты по дням' }).locator('table').count());
await page.locator('.widget', { hasText: 'Визиты по дням' }).locator('.widget-toggle').click();

// 5. Hover states.
const chartSvg = page.locator('.widget', { hasText: 'Визиты по дням' }).locator('svg.line-svg');
const cb = await chartSvg.boundingBox();
await page.mouse.move(cb.x + cb.width * 0.6, cb.y + cb.height * 0.4);
await page.waitForTimeout(150);
await page.screenshot({ path: '/tmp/shot-tools/line-tooltip.png' });
const bar = page.locator('.bar-row').nth(1);
await bar.hover();
await page.waitForTimeout(150);
await page.screenshot({ path: '/tmp/shot-tools/bar-tooltip.png' });
console.log('bar tooltip:', await page.locator('.tooltip').allInnerTexts());

// 6. Reset layout.
await page.getByRole('button', { name: 'Сбросить раскладку' }).click();
await page.waitForTimeout(300);
await check('after reset');
console.log(errors.join('\n') || 'no console errors');
await page.screenshot({ path: '/tmp/shot-tools/after-interact.png', fullPage: true });
await browser.close();
EOF
export FONTCONFIG_FILE=/tmp/fonts/fonts.conf LD_LIBRARY_PATH=$(find /tmp/chromelibs -name "*.so*" -printf "%h\n" | sort -u | tr '\n' ':') && timeout 200 node interact.mjs 2>&1 | grep -v -E "bus.cc|bluez|sandbox_linux|viz_main|Fontconfig" | tail -40

