await page.waitForTimeout(300);
await page.getByText('90 дней', { exact: true }).click();
await page.waitForTimeout(400);
const kpi = await page.locator('.widget', { has: page.getByRole('heading', { name: 'Выручка', exact: true }) }).locator('.kpi-value').innerText();
console.log('revenue KPI for 90 days:', kpi);
await page.screenshot({ path: '/tmp/shot-tools/period90.png' });
console.log(errors.join('\n') || 'no errors');
