export FONTCONFIG_FILE=/tmp/fonts/fonts.conf LD_LIBRARY_PATH=$(find /tmp/chromelibs -name "*.so*" -printf "%h\n" | sort -u | tr '\n' ':') && timeout 200 node narrow.mjs 2>&1 | grep -v -E "bus.cc|bluez|sandbox_linux|viz_main|Fontconfig" | tail -20
